/**
 * Request body shared by `POST /chat` and `POST /title`. Tools/actions are never accepted from the client — they are resolved server-side per turn.
 * @public
 */
export interface ChatRequest {
  /**
   * Id of the assistant to converse with.
   */
  assistantId: string;
  /**
   * The `provider:model` id to use for this turn.
   */
  modelId: string;
  /**
   * How hard the model should think on this turn. Applied only when the chosen model is flagged `reasoning`; otherwise ignored and the provider\'s default applies.
   */
  reasoningLevel?: ChatRequestReasoningLevelEnum;
  /**
   * The conversation (thread) this turn belongs to. Sent by `/chat` so the backend can persist the completed turn server-side. Optional; omitted by `/title` and by the first turn of a not-yet-created thread.
   */
  threadId?: string;
  /**
   * The conversation as a non-empty array of UI messages. The internal shape of each message is intentionally not over-constrained here.
   */
  messages: Array<any>;
}

/**
 * @public
 */
export type ChatRequestReasoningLevelEnum = 'low' | 'medium' | 'high' | 'max';
